package com.telecom.tollfree.service;
import com.telecom.tollfree.api.ApiModels.*; import com.telecom.tollfree.domain.*; import com.telecom.tollfree.messaging.NumberEventPublisher; import com.telecom.tollfree.repository.ProvisioningRequestRepository; import org.junit.jupiter.api.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ProvisioningServiceTest {@Test void delegatesReserveAndPersistsRequest(){var repo=mock(ProvisioningRequestRepository.class);var customers=mock(CustomerService.class);var numbers=mock(NumberService.class);var events=mock(NumberEventPublisher.class);Customer c=new Customer(); when(customers.require("c")).thenReturn(c);when(numbers.reserve(eq("8001234567"),same(c))).thenReturn(new NumberView("8001234567",NumberStatus.RESERVED,null));when(repo.save(any())).thenAnswer(i->i.getArgument(0));var result=new ProvisioningService(repo,customers,numbers,events).provision(new ProvisionInput("c","8001234567"));assertFalse(result.idempotent());verify(numbers).reserve(eq("8001234567"),same(c));} @Test void repeatRequestIsIdempotent(){var repo=mock(ProvisioningRequestRepository.class);var numbers=mock(NumberService.class);ProvisioningRequest prior=new ProvisioningRequest("c","8001234567");when(repo.findByCustomerIdAndNumber("c","8001234567")).thenReturn(Optional.of(prior));when(numbers.status("8001234567")).thenReturn(new NumberView("8001234567",NumberStatus.RESERVED,"c"));var result=new ProvisioningService(repo,mock(CustomerService.class),numbers,mock(NumberEventPublisher.class)).provision(new ProvisionInput("c","8001234567"));assertTrue(result.idempotent());verify(numbers,never()).reserve(any(),any());} @Test void invalidNumberPublishesFailure(){var repo=mock(ProvisioningRequestRepository.class);var customers=mock(CustomerService.class);var numbers=mock(NumberService.class);var events=mock(NumberEventPublisher.class);when(customers.require("c")).thenThrow(new NotFoundException("Customer not found"));assertThrows(NotFoundException.class,()->new ProvisioningService(repo,customers,numbers,events).provision(new ProvisionInput("c","8001234567")));verify(events).publish(argThat(e->e.eventType().equals("ProvisioningFailed")));}}
